    function renderSuggestions(box,input){const q=normalizeArabic(input.value),type=input.closest('.search-wrap')?.dataset.searchType||getLastTab(),pool=suggestionPool(type),seen=new Set(),ranked=[];for(const candidate of pool){const text=String(candidate.text||'').trim(),normalized=normalizeArabic(text);if(!text||seen.has(normalized))continue;seen.add(normalized);let score=0;if(!q){score=candidate.kind==='بحث سابق'?500:candidate.kind==='الأكثر بحثًا'?400:candidate.kind===TAB_SUGGESTION_LABELS[type]?300:200;}else{const exact=normalized===q,phrase=normalized.startsWith(q),word=normalized.split(' ').some(part=>part.startsWith(q)),inside=normalized.includes(q),distance=levenshtein(q,normalized.slice(0,Math.max(q.length,normalized.length)));score=exact?600:phrase?500:word?380:inside?260:(distance<=2?180:0);}if(score>0)ranked.push({text,kind:candidate.kind,score});}const list=ranked.sort((a,b)=>b.score-a.score||a.text.localeCompare(b.text,'ar')).slice(0,7);box.innerHTML=list.map((item,i)=>'<button class="suggestion" type="button" data-index="'+i+'" data-suggest="'+esc(item.text)+'" aria-label="بحث عن '+esc(item.text)+'" aria-selected="false" tabindex="-1">'+icon+'<span>'+esc(item.text)+'</span><small>'+esc(item.kind)+'</small></button>').join('');box.dataset.active='-1';box.hidden=!list.length;box.querySelectorAll('[data-suggest]').forEach(b=>b.addEventListener('mousedown',e=>{e.preventDefault();selectSuggestion(input,box,b);}));}
