    async function fetchSearchData(q,page,type){const urlParams=new URLSearchParams(location.search),filters=type==='news'?['category','source'].map(k=>[k,urlParams.get(k)||'']).filter(([,v])=>v):[],filterKey=filters.map(([k,v])=>`${k}:${v}`).join('|'),cacheKey=`bardy:v8:result:${type}:${q.trim()}:page:${page}:${filterKey}`;let cached=null;try{cached=JSON.parse(sessionStorage.getItem(cacheKey)||'null');}catch{};let data=cached&&Date.now()-cached.savedAt<300000?cached.data:null;if(!data){const endpoint=new URL(`${WORKER}/${encodeURIComponent(type)}`, location.origin);endpoint.searchParams.set('q',q);endpoint.searchParams.set('page',String(page));filters.forEach(([k,v])=>endpoint.searchParams.set(k,v));const timeoutMs=type==='news'?12000:40000;data=await fetchWorkerUrl(endpoint.toString(),{cache:'default'},type==='images'?1:2);if(!data.success){await new Promise(resolve=>setTimeout(resolve,220));data=await fetchWorkerUrl(endpoint.toString(),{cache:'default'},2);}if(!data.success)throw Error(data.error||'search failed');try{sessionStorage.setItem(cacheKey,JSON.stringify({savedAt:Date.now(),data}));}catch{}}return data;}
    function textCard(item,lead=false){const rawTitle=String(item.title||'معلومة بدون عنوان'),title=esc(rawTitle),full=String(item.text||item.description||'لا يوجد وصف متاح.'),limit=500,hasMore=full.length>limit,short=hasMore?full.slice(0,limit).trimEnd()+'…':full,image=item.thumbnail||item.image_url||'',readerButton=hasMore?`<button class="read-more-button" type="button" data-reader-title="${esc(rawTitle)}" data-reader-text="${esc(full)}" data-reader-image="${esc(image)}" data-reader-source="${esc(item.source||'ويكيبيديا')}">${lead?'إكمال القراءة':'قراءة النص كاملًا'}</button>`:'';if(lead)return `<article class="info-lead">${image?`<img referrerpolicy="no-referrer" class="lead-image" src="${esc(image)}" alt="${esc(item.image_alt||item.title||'')}" loading="eager">`:''}<div><h3><a href="${esc(item.url||'#')}" target="_blank" rel="noopener noreferrer">${title}</a></h3><p>${esc(short)}</p>${readerButton}<div class="card-meta">${esc(item.source||'ويكيبيديا')}</div></div></article>`;return `<article class="info-card"><h3><a href="${esc(item.url||'#')}" target="_blank" rel="noopener noreferrer">${title}</a></h3><p>${esc(short)}</p>${readerButton}<div class="card-meta">${esc(item.source||'ويكيبيديا')}</div></article>`;}
    function galleryMarkup(images,title='معرض الصور'){const safeImages=(images||[]).filter(x=>x.image_url||x.url);if(!safeImages.length)return '';const first=safeImages[0],galleryId='gallery-'+Math.random().toString(36).slice(2),serialized=esc(JSON.stringify(safeImages.map(x=>({src:x.image_url||x.url,title:x.title||title,url:x.url||''}))));const thumbs=safeImages.map((item,index)=>`<button class="gallery-thumb ${index===0?'active':''}" type="button" data-gallery-thumb data-index="${index}" aria-label="الصورة ${index+1}"><img referrerpolicy="no-referrer" src="${esc(item.image_url||item.url)}" alt="" loading="lazy"></button>`).join('');return `<section class="result-section"><div class="section-heading"><h2>${esc(title)}</h2></div><div class="media-gallery" data-gallery="${galleryId}" data-gallery-images='${serialized}'><button class="gallery-hero" type="button" data-gallery-open data-index="0"><img referrerpolicy="no-referrer" src="${esc(first.image_url||first.url)}" alt="${esc(first.title||title)}" loading="eager"><span class="gallery-open-label">اضغط للتكبير</span></button><div class="gallery-strip">${thumbs}</div></div></section>`;}
    function imageGridMarkup(images,title='معرض الصور'){const safeImages=(images||[]).filter(x=>x.image_url||x.url);if(!safeImages.length)return '';const serialized=esc(JSON.stringify(safeImages.map(x=>({src:x.image_url||x.url,title:x.title||title,url:x.url||''}))));const cards=safeImages.map((item,index)=>`<button class="image-grid-card" type="button" data-grid-open data-index="${index}" aria-label="فتح صورة ${esc(item.title||`رقم ${index+1}`)}"><span class="image-grid-media"><img referrerpolicy="no-referrer" src="${esc(item.image_url||item.url)}" alt="${esc(item.title||title)}" loading="lazy" decoding="async" onerror="this.onerror=null;(window.bardyImgFail||function(i){i.src='/assets/site-placeholder.svg'})(this)"${index<2?' fetchpriority="high"':''}></span><span class="image-grid-info"><span class="image-grid-title">${esc(item.title||'صورة بدون عنوان')}</span>${item.source?`<span class="image-grid-source">${esc(item.source)}</span>`:''}<span class="image-grid-url">اضغط للتكبير</span></span></button>`).join('');return `<section class="result-section"><div class="section-heading"><h2>${esc(title)}</h2><span>${safeImages.length} صورة</span></div><div class="image-grid" data-image-grid data-image-grid-images='${serialized}'>${cards}</div></section>`;}
    function mediaStack(items,title){if(!items?.length)return '';return `<section class="result-section"><div class="section-heading"><h2>${esc(title)}</h2><span>${items.length} نتائج</span></div><div class="media-stack">${items.map((item,index)=>`<article class="media-card">${item.image_url?`<img referrerpolicy="no-referrer" class="media-thumb" src="${esc(item.image_url)}" alt="${esc(item.title||'')}" loading="lazy" decoding="async"${index<2?' fetchpriority="high"':''}>`:'<div class="media-thumb media-thumb-empty" aria-label="صورة الوسيط غير متاحة"><span>وسيط</span></div>'}<div class="media-copy"><h3><a href="${esc(item.url||item.video_url||'#')}" target="_blank" rel="noopener noreferrer">${esc(item.title||'وسيط بدون عنوان')}</a></h3><p>${esc(item.description||item.source||'اضغط لفتح المحتوى')}</p>${item.source?`<div class="media-source">${esc(item.source)}</div>`:''}</div></article>`).join('')}</div></section>`;}
    function webStack(items,type){if(!items?.length)return '<div class="empty web-empty"><strong>لم نجد نتائج ويب مطابقة.</strong><span>جرّب كلمة أكثر تحديدًا أو صياغة مختلفة.</span></div>';return `<section class="result-section web-results-section"><div class="section-heading"><h2>نتائج الويب</h2><span>${items.length} نتيجة</span></div><div class="web-stack">${items.map(item=>{const host=(()=>{try{return new URL(item.url).hostname.replace(/^www\./,'')}catch{return ''}})(),logo=item.icon_url||item.logo||`https://www.google.com/s2/favicons?domain=${encodeURIComponent(host)}&sz=64`;return `<article class="result"><div class="result-top"><img referrerpolicy="no-referrer" class="result-logo" src="${esc(logo)}" alt="" loading="lazy" onerror="this.onerror=null;this.src='/assets/site-placeholder.svg'"><div class="result-copy"><h2><a href="${esc(item.url||'#')}" target="_blank" rel="noopener noreferrer">${esc(item.title||'نتيجة بدون عنوان')}</a></h2><div class="result-url">${esc(compactUrl(item.url||''))}</div><p>${esc(item.description||'لا يوجد وصف لهذه النتيجة.')}</p><a class="result-open-link" href="${esc(item.url||'#')}" target="_blank" rel="noopener noreferrer">فتح النتيجة ↗</a></div></div></article>`}).join('')}</div></section>`;}
    const NEWS_ARTICLE_STORE_KEY='bardy:news-articles:v1';
    function newsSourceUrl(item){for(const value of [item?.url,item?.link,item?.href,item?.canonical_url,item?.source_url,item?.permalink,item?.original_url]){const raw=String(value||'').trim();if(!raw||raw==='#')continue;try{const url=new URL(raw,location.origin);if(url.protocol==='http:'||url.protocol==='https:')return url.href;}catch{}}return ''; }
    function newsArticleId(item){return String(item?.id||item?.guid||newsSourceUrl(item)||item?.title||'خبر').trim().slice(0,1000)||'خبر';}
    function storeNewsArticles(items){try{const stored=JSON.parse(sessionStorage.getItem(NEWS_ARTICLE_STORE_KEY)||'{}');const articles=stored&&typeof stored==='object'&&!Array.isArray(stored)?stored:{};for(const item of items){const id=newsArticleId(item);if(!id)continue;delete articles[id];articles[id]={id,title:String(item.title||'خبر بدون عنوان').slice(0,500),text:String(item.full_text||item.fullText||item.text||item.content||item.description||item.summary||'').slice(0,5000),description:String(item.description||item.summary||'').slice(0,5000),category:String(item.category||item.section||'أخبار').slice(0,100),source:String(item.source||item.sourceName||item.publisher||'مصدر الخبر').slice(0,300),sourceName:String(item.sourceName||item.source||item.publisher||'').slice(0,300),publishedAt:String(item.publishedAt||item.published_at||item.date||'').slice(0,100),date:String(item.date||item.publishedAt||item.published_at||'').slice(0,100),image_url:String(item.image_url||item.image||item.thumbnail||'').slice(0,2048),image:String(item.image||item.image_url||item.thumbnail||'').slice(0,2048),image_alt:String(item.image_alt||item.title||'').slice(0,500),url:newsSourceUrl(item).slice(0,3000),link:newsSourceUrl(item).slice(0,3000)};}const currentIds=new Set(items.map(newsArticleId)),storedIds=Object.keys(articles),excess=Math.max(0,storedIds.length-Math.max(80,currentIds.size));for(const oldId of storedIds.filter(id=>!currentIds.has(id)).slice(0,excess))delete articles[oldId];sessionStorage.setItem(NEWS_ARTICLE_STORE_KEY,JSON.stringify(articles));}catch{}}
    function newsArticleHref(item){const clean=(value,limit)=>String(value??'').trim().slice(0,limit);const title=clean(item?.title||'خبر بدون عنوان',300),description=clean(item?.description||item?.summary||item?.text||'',300),image=clean(item?.image_url||item?.image||item?.thumbnail||'',1200),source=clean(item?.source||item?.sourceName||'',120),url=clean(newsSourceUrl(item),1500);const params=new URLSearchParams({id:newsArticleId(item),title,description,image,source,url,back:`${location.pathname}${location.search}`});return `/article?${params.toString()}`;}
    function newsStack(items){if(!items?.length)return '<div class="empty">لم نجد أخبارًا مطابقة. جرّب عبارة أخرى.</div>';storeNewsArticles(items);return `<section class="result-section"><div class="news-stack">${items.map(item=>{const image=item.image_url||item.image||item.thumbnail||'',title=item.title||'خبر بدون عنوان',href=newsArticleHref(item),sourceUrl=newsSourceUrl(item);return `<article class="news-card"><a class="news-card-image-link" href="${esc(href)}" aria-label="قراءة الخبر: ${esc(title)}">${image?`<img referrerpolicy="no-referrer" class="news-card-cover" src="${esc(image)}" alt="" loading="lazy" decoding="async" onerror="this.onerror=null;this.src='/assets/news-placeholder.svg'">`:`<img class="news-card-cover" src="/assets/news-placeholder.svg" alt="صورة خبر مؤقتة" loading="lazy">`}</a><div class="news-card-body"><h3><a href="${esc(href)}">${esc(title)}</a></h3><div class="result-url">${esc(compactUrl(sourceUrl))}</div><p>${esc(item.description||item.summary||'لا يوجد ملخص لهذا الخبر.')}</p><div class="news-card-meta">${esc(item.source||item.sourceName||'مصدر الخبر')}</div><a class="news-read-link" href="${esc(href)}">اقرأ الخبر</a></div></article>`}).join('')}</div></section>`;}
    function standardStack(items,type){if(!items?.length)return '<div class="empty">لم نجد نتائج مطابقة. جرّب عبارة أخرى.</div>';return `<section class="result-section"><div class="media-stack">${items.map(item=>`<article class="media-card"><div class="result-logo">${icon}</div><div><h3><a href="${esc(item.url||'#')}" target="_blank" rel="noopener noreferrer">${esc(item.title||'نتيجة بدون عنوان')}</a></h3><div class="result-url">${esc(compactUrl(item.url||''))}</div><p>${esc(item.description||'لا يوجد وصف لهذه النتيجة.')}</p></div></article>`).join('')}</div></section>`;}

    function answerFromData(data){return String(data?.items?.[0]?.text||data?.items?.[0]?.description||data?.answer||'تعذر استخراج إجابة من النموذج.').trim();}
    function answerMarkup(value,sources=[]){const byId=new Map((Array.isArray(sources)?sources:[]).map((s,i)=>[String(s?.id||i+1),s]));return esc(String(value||'')).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/^\s*[-•]\s+/gm,'<span class="answer-bullet">•</span> ').replace(/\[(\d{1,2})\]/g,(mark,n)=>{const s=byId.get(String(Number(n)));const url=String(s?.url||'');if(!/^https?:\/\//i.test(url))return '';let host='';try{host=new URL(url).hostname.replace(/^www\./,'');}catch{return '';}return `<a class="answer-cite" href="${esc(url)}" target="_blank" rel="noopener noreferrer" title="${esc(s.title||host)}">${esc(host)}</a>`;}).replace(/\n/g,'<br>');}
    function answerSourcesMarkup(data){const sources=Array.isArray(data?.sources)?data.sources:[];if(!sources.length)return '';return `<section class="answer-sources" aria-label="مصادر الإجابة"><div class="answer-sources-head"><h2>المصادر المستخدمة</h2><span>${sources.length} ${sources.length===1?'مصدر':'مصادر'}</span></div><ol>${sources.map((source,index)=>{const label=esc(source.title||'مصدر موثوق');return `<li><span class="answer-source-number">${esc(source.id||index+1)}</span><div>${source.url?`<a href="${esc(source.url)}" target="_blank" rel="noopener noreferrer">${label}</a>`:`<span class="answer-source-title">${label}</span>`}<span>${esc(source.source||'مصدر خارجي')}</span></div></li>`;}).join('')}</ol></section>`;}
    function renderAnswerCard(data,q,overview=false){const answer=answerFromData(data),sources=Array.isArray(data?.sources)?data.sources:[],displayAnswer=answer.replace(/\s*\[(\d+)\]/g,(mark,index)=>sources.some((s,i)=>String(s?.id||i+1)===String(Number(index)))?mark:''),uncertain=data?.status==='insufficient_sources'||/لا أستطيع تأكيد|لا يمكن الإجابة|غير متأكد|لا توجد معلومات/.test(answer),kicker=overview?'نظرة عامة بالذكاء الاصطناعي':uncertain?'إجابة تحتاج إلى مراجعة':'إجابة مبنية على المصادر',badge=overview?(sources.length?'مصادر قابلة للمراجعة':'تحقق من نتائج الويب أدناه'):'مدعوم بمصادر قابلة للمراجعة',foot=overview?(sources.length?'راجع المصادر قبل الاعتماد على الإجابة.':'تحقق من المعلومات عبر نتائج الويب أدناه.'):(uncertain?'المصادر المتاحة لا تكفي للتأكيد؛ راجع الروابط قبل الاعتماد.':'راجع المصادر قبل الاعتماد على الإجابة.');return `<article class=\"answer-card ${uncertain?'answer-card-uncertain':''} ${overview?'web-answer-overview':''}\" aria-label=\"إجابة Bardy AI\"><header class=\"answer-card-head\"><div class=\"answer-card-brand\"><span class=\"answer-card-mark\" aria-hidden=\"true\">✦</span><div><span class=\"answer-card-kicker\">${kicker}</span><h1>Bardy AI</h1></div></div><span class=\"answer-card-source\">${badge}</span></header><div class=\"answer-card-question\"><span>سؤالك</span><strong>${esc(q||data?.query||'سؤالك')}</strong></div><div class=\"answer-card-answer-label\">الإجابة</div><div class=\"answer-card-body\">${answerMarkup(displayAnswer,sources)}</div>${overview&&!sources.length?'':answerSourcesMarkup(data)}<footer class=\"answer-card-foot\"><span class=\"answer-card-foot-icon\" aria-hidden=\"true\">✓</span>${foot}</footer></article>`;}
    function answerLoadingCard(q){return `<article class="answer-card answer-card-loading" aria-live="polite"><header class="answer-card-head"><div class="answer-card-brand"><span class="answer-card-mark" aria-hidden="true">✦</span><div><span class="answer-card-kicker">جارٍ تجهيز الإجابة</span><h1>Bardy AI</h1></div></div><span class="answer-card-source">نبحث في المصادر</span></header><div class="answer-card-question"><span>سؤالك</span><strong>${esc(q||'سؤالك')}</strong></div><div class="answer-loading-line">نحلل المصادر ونرتب إجابة واضحة لك…</div><div class="answer-loading-bar"></div></article>`;}
