    function webLanding(){return `<section class="web-closed" aria-labelledby="webClosedTitle"><div class="web-closed-mark" aria-hidden="true">✦</div><h1 id="webClosedTitle">قريبًا... اكتمال الرؤية</h1><p>نحن على وشك الانتهاء من تطوير فهرس الويب في بردي. نطمح لتوفير كل الخدمات في مكان واحد، مع تجربة بحث واضحة ومفيدة تناسب المستخدم المصري.</p><p class="web-closed-note">سنقدم نتائج من مواقع تقدم محتوى نظيفًا، قليل الإعلانات قدر الإمكان، ومتاحًا مجانًا بدون اشتراكات، مع الحرص على توفير أفضل خدمة ممكنة.</p><ul class="web-closed-points"><li>محتوى نظيف</li><li>مجاني بدون اشتراكات</li><li>أقل قدر من الإعلانات</li><li>خدمة أفضل للمستخدم</li></ul></section>`;}
    function localLanding(){return `<section class="web-closed" aria-labelledby="localClosedTitle"><div class="web-closed-mark" aria-hidden="true">⌂</div><h1 id="localClosedTitle">قريبًا... دليل الأنشطة المحلية</h1><p>اكتب ما تحتاجه ومكانه، مثل: دكتور في الزقازيق، محامي، سباك، مدرس، صيدلية، محل أو سوبر ماركت.</p><p class="web-closed-note">نطمح لمساعدتك في الوصول إلى النشاط المناسب بالقرب منك، مع عرض بيانات التواصل وساعات العمل والتقييمات، ثم توفير إمكانية التواصل والحجز مباشرة عندما تتوفر الخدمة.</p><ul class="web-closed-points"><li>أطباء وخدمات طبية</li><li>محامون وحرفيون</li><li>محلات وسوبر ماركت</li><li>تواصل وحجز لاحقًا</li></ul></section>`;}
    function eventCard(item){const title=item?.title||'مناسبة بدون عنوان',date=item?.date||'موعد غير محدد',description=item?.description||'لا يوجد وصف إضافي لهذه المناسبة.';return `<article class="event-card"><div class="event-date"><strong>${esc(date)}</strong><span>${esc(item?.calendar||'')}</span></div><div class="event-copy"><h3>${esc(title)}</h3><p>${esc(description)}</p><div class="event-meta">${esc(item?.category||'مناسبة')} ${item?.calendar?` · ${esc(item.calendar)}`:''}</div></div></article>`;}
    function eventsStack(data){const upcoming=Array.isArray(data?.upcoming)?data.upcoming:[],past=Array.isArray(data?.past)?data.past:[],counts=data?.counts||{};if(!upcoming.length&&!past.length)return '<div class="empty">لا توجد مناسبات متاحة حاليًا.</div>';return `<div class="events-stack"><section class="events-current-hero" aria-labelledby="eventsCurrentTitle"><div class="events-current-mark" aria-hidden="true">✦</div><div><span class="events-current-kicker">دليل بردي للمناسبات</span><h1 id="eventsCurrentTitle">الأحداث الجارية في مصر</h1><p>المناسبات المتاحة الآن مرتبة حسب القادم، مع سجل مختصر للمناسبات الفائتة.</p><div class="events-current-meta"><span>${Number(counts.upcoming||upcoming.length)} قادمة</span><span>${Number(counts.past||past.length)} فائتة</span><span>بتوقيت القاهرة</span></div></div></section>${upcoming.length?`<section class="result-section events-section"><div class="section-heading"><h2>المناسبات القادمة</h2><span>${upcoming.length} مناسبة</span></div><div class="event-list">${upcoming.map(eventCard).join('')}</div></section>`:''}${past.length?`<section class="result-section events-section events-past"><div class="section-heading"><h2>المناسبات الفائتة</h2><span>${past.length} مناسبة</span></div><div class="event-list">${past.map(eventCard).join('')}</div></section>`:''}</div>`;}
    function renderResults(data,type,q,infoData=null){const items=data.items||data.results||[];if(type==='info'){const infoItems=items.filter(x=>x.type==='info'||!x.type),images=items.filter(x=>x.type==='image'||x.image_url||x.thumbnail).map(x=>mediaItem(x,'images',q)),videos=items.filter(x=>x.type==='video'||x.video_url).map(x=>mediaItem(x,'videos',q)),primary=infoItems[0],second=infoItems.slice(1,2),laterInfo=infoItems.slice(2);return `<div class="results-shell">${primary?`<section class="result-section">${textCard(primary,true)}</section>`:''}${second.length?`<section class="result-section"><div class="section-heading"><h2>معلومة أخرى</h2></div><div class="text-results">${second.map(x=>textCard(x)).join('')}</div></section>`:''}${images.length?galleryMarkup(images,'صور مرتبطة بالمعلومة'):''}${laterInfo.length?`<section class="result-section"><div class="section-heading"><h2>معلومات إضافية</h2></div><div class="text-results">${laterInfo.map(x=>textCard(x)).join('')}</div></section>`:''}${videos.length?mediaStack(videos,'فيديوهات مرتبطة'):''}${!primary&&!images.length&&!videos.length?'<div class="empty">لم نجد معلومات أو وسائط مطابقة.</div>':''}</div>`;}if(type==='images')return imageGridMarkup(items.map(x=>mediaItem(x,'images',q)),'معرض الصور')||standardStack(items,type);if(type==='videos')return mediaStack(items.map(x=>mediaItem(x,'videos',q)),'الفيديوهات')||standardStack(items,type);if(type==='news')return newsStack(items);if(type==='events')return eventsStack(data);if(type==='web')return webStack(items,type);if(type==='local')return localLanding();if(type==='answers'){const answer=data?.success?renderAnswerCard(data,q):answerErrorCard(q);const supporting=infoData?.success?`<section class="ai-supporting-results"><div class="section-heading"><h2>المعلومات والوسائط</h2><span>من نتائج البحث</span></div>${renderResults(infoData,'info',q)}</section>`:'';return `<div class="ai-results-stack">${answer}${supporting}</div>`;}return standardStack(items,type);}
    function setupReaderInteractions(){document.querySelectorAll('[data-reader-text]').forEach(button=>button.addEventListener('click',()=>{let modal=document.getElementById('readerModal');if(!modal){modal=document.createElement('div');modal.id='readerModal';modal.className='reader-modal';modal.innerHTML='<div class="reader-panel" role="dialog" aria-modal="true" aria-labelledby="readerTitle"><button class="reader-close" type="button" aria-label="إغلاق">×</button><div class="reader-content"></div></div>';document.body.appendChild(modal);modal.addEventListener('click',e=>{if(e.target===modal||e.target.closest('.reader-close'))modal.classList.remove('open');});modal.querySelector('.reader-close').addEventListener('click',()=>modal.classList.remove('open'));}const image=button.dataset.readerImage,title=button.dataset.readerTitle||'معلومة',text=button.dataset.readerText||'',source=button.dataset.readerSource||'';modal.querySelector('.reader-content').innerHTML=`${image?`<img referrerpolicy="no-referrer" src="${esc(image)}" alt="${esc(title)}">`:''}<h2 id="readerTitle">${esc(title)}</h2><p>${esc(text)}</p>${source?`<div class="card-meta">${esc(source)}</div>`:''}`;modal.classList.add('open');document.body.style.overflow='hidden';modal.addEventListener('click',()=>{if(!modal.classList.contains('open'))document.body.style.overflow='';},{once:true});}));}
    function setupMediaInteractions(){document.querySelectorAll('[data-gallery]').forEach(gallery=>{const images=JSON.parse(gallery.dataset.galleryImages||'[]'),hero=gallery.querySelector('[data-gallery-open]'),img=hero?.querySelector('img');gallery.querySelectorAll('[data-gallery-thumb]').forEach(thumb=>thumb.addEventListener('click',()=>{const index=Number(thumb.dataset.index),item=images[index];if(!item)return;img.src=item.src;img.alt=item.title||'';gallery.querySelectorAll('[data-gallery-thumb]').forEach(x=>x.classList.toggle('active',x===thumb));hero.dataset.index=String(index);}));hero?.addEventListener('click',()=>openLightbox(images,Number(hero.dataset.index||0)));});document.querySelectorAll('[data-image-grid]').forEach(grid=>{const images=JSON.parse(grid.dataset.imageGridImages||'[]');grid.querySelectorAll('[data-grid-open]').forEach(card=>card.addEventListener('click',()=>openLightbox(images,Number(card.dataset.index||0))));});}
    function openLightbox(images,index){let box=document.getElementById('mediaLightbox');if(!box){box=document.createElement('div');box.id='mediaLightbox';box.className='lightbox';box.innerHTML='<div class="lightbox-panel" role="dialog" aria-modal="true"><button class="lightbox-close" type="button" aria-label="إغلاق">×</button><button class="lightbox-nav lightbox-prev" type="button" aria-label="الصورة السابقة">›</button><button class="lightbox-nav lightbox-next" type="button" aria-label="الصورة التالية">‹</button><img class="lightbox-image" alt=""><div class="lightbox-caption"></div></div>';document.body.appendChild(box);box.addEventListener('click',e=>{if(e.target===box||e.target.closest('.lightbox-close'))box.classList.remove('open');});box.querySelector('.lightbox-prev').addEventListener('click',()=>show(-1));box.querySelector('.lightbox-next').addEventListener('click',()=>show(1));}box._images=images;box._index=index;box.classList.add('open');show(0);function show(delta){box._index=(box._index+delta+box._images.length)%box._images.length;const item=box._images[box._index];box.querySelector('.lightbox-image').src=item.src;box.querySelector('.lightbox-image').alt=item.title||'';box.querySelector('.lightbox-caption').textContent=item.title||'';}}

    async function runSearch(q,page=1,type=DEFAULT_SEARCH_TYPE){document.body.dataset.view='results';document.querySelector('.top').style.display='none';document.querySelector('footer').style.display='none';document.getElementById('app').innerHTML=`<section class="results-page"><header class="results-header"><button class="mobile-menu-button" type="button" data-menu-open aria-label="فتح قائمة بردي" aria-expanded="false">☰</button><a href="#" class="top-brand" id="resultsHome"><img class="logo-image" src="/assets/bardy-logo.webp" alt="بردي"></a><div class="results-hero-logo"><img src="/assets/bardy-logo.webp" alt="بردي"></div>${searchBox(q,'resultsSearch',type)}<img class="flag-logo" src="/assets/flag-search-logo.webp" alt="علم مصر وعدسة البحث"></header><main class="results-main"><p class="query-suggestion" id="querySuggestion" hidden></p><div class="news-filters" id="newsFilters" ${type==='news'?'':'hidden'}></div><section class="result-list" id="resultList"></section><nav class="pagination" aria-label="صفحات النتائج" hidden></nav></main></section>`;document.getElementById('resultsHome').addEventListener('click',e=>{e.preventDefault();home();});bindSearch();document.querySelector('.search-tab.active')?.scrollIntoView({block:'nearest',inline:'center'});if(type==='local'){document.getElementById('resultList').innerHTML=localLanding();restoreScroll();return;}try{const defaultQuery=['answers','info','images','videos','news'].includes(type)&&!q?'مصر':q;const loadingList=document.getElementById('resultList');if((type==='web'||type==='images')&&String(q||'').length>SEARCH_QUERY_MAX){loadingList.innerHTML=queryTooLongCard(q,SEARCH_QUERY_MAX);restoreScroll();return;}if(type==='answers')loadingList.innerHTML=answerLoadingCard(defaultQuery);if(type==='web')loadingList.innerHTML=webLoadingCard();if(type==='images')loadingList.innerHTML=imageLoadingCard();if(type==='events')loadingList.innerHTML='<section class="web-loading-card" aria-live="polite"><div class="web-loading-icon">✦</div><h2>جارٍ تحميل المناسبات</h2><p>نرتب المناسبات القادمة ثم نعرض الفائتة.</p><div class="answer-loading-bar"></div></section>';let data=null,infoData=null,webAnswerPromise=null;if(type==='answers'){const [answerResult,infoResult]=await Promise.allSettled([fetchSearchData(defaultQuery,page,'answers'),fetchSearchData(defaultQuery,page,'info')]);data=answerResult.status==='fulfilled'?answerResult.value:null;infoData=infoResult.status==='fulfilled'?infoResult.value:null;}else{if(type==='web'&&page===1&&defaultQuery.trim())webAnswerPromise=fetchSearchData(defaultQuery,1,'answers').catch(()=>null);data=await fetchSearchData(defaultQuery,page,type);}if(!data?.success)throw Error(data?.error||'search failed');if(type==='news')renderNewsFilters(data);const suggestion=document.getElementById('querySuggestion');if(suggestion&&data.suggestion&&data.rewrittenQuery&&data.rewrittenQuery!==q){suggestion.hidden=false;suggestion.innerHTML='<span>'+esc(data.suggestion)+'</span> <button type="button" class="use-suggestion" data-use-rewrite>استخدم الاقتراح</button>';suggestion.querySelector('[data-use-rewrite]').addEventListener('click',()=>{location.href=tabPagePath(type)+'?q='+encodeURIComponent(data.rewrittenQuery);});}const status=document.getElementById('resultStatus');if(status)status.textContent='';const list=document.getElementById('resultList');renderPagination(data,type);list.innerHTML=renderResults(data,type,defaultQuery,infoData);if(type==='web'&&webAnswerPromise){const overview=document.createElement('div');overview.className='web-ai-overview-slot';overview.innerHTML=answerLoadingCard(defaultQuery);list.insertBefore(overview,list.firstChild);const timeout=new Promise(resolve=>setTimeout(()=>resolve(null),15000));Promise.race([webAnswerPromise,timeout]).then(answerData=>{if(!overview.isConnected)return;const text=answerData?.items?.[0]?.text||answerData?.items?.[0]?.description||answerData?.answer;if(!answerData?.success||!text){overview.remove();return;}overview.innerHTML=renderAnswerCard(answerData,defaultQuery,true);}).catch(()=>overview.remove());}setupReaderInteractions();setupMediaInteractions();restoreScroll();}catch(e){const status=document.getElementById('resultStatus');if(status)status.textContent='تعذر تنفيذ البحث';const list=document.getElementById('resultList');list.innerHTML=e?.code==='query_too_long'?queryTooLongCard(q,e.maxLength||SEARCH_QUERY_MAX):type==='answers'?answerErrorCard(q):type==='web'?webErrorCard(q):type==='images'?imageErrorCard(q):'<div class="empty">تعذر تنفيذ البحث حاليًا. حاول مرة أخرى.</div>';if(['answers','web','images'].includes(type))list.querySelector('.answer-retry')?.addEventListener('click',()=>runSearch(q,page,type));console.error(e);}}
    const drawer=document.querySelector('[data-mobile-drawer]'),backdrop=document.querySelector('[data-menu-backdrop]');function closeMenu(){if(!drawer)return;drawer.classList.remove('open');backdrop.classList.remove('open');drawer.setAttribute('aria-hidden','true');document.querySelectorAll('[data-menu-open]').forEach(b=>b.setAttribute('aria-expanded','false'));}function openMenu(){if(!drawer)return;drawer.classList.add('open');backdrop.classList.add('open');drawer.setAttribute('aria-hidden','false');document.querySelectorAll('[data-menu-open]').forEach(b=>b.setAttribute('aria-expanded','true'));}document.addEventListener('click',e=>{if(e.target.closest('[data-menu-open]'))openMenu();else if(e.target.closest('[data-menu-close]')||e.target.closest('[data-menu-backdrop]'))closeMenu();});document.addEventListener('keydown',e=>{if(e.key==='Escape')closeMenu();});document.getElementById('topHome').addEventListener('click',e=>{e.preventDefault();location.href='/';});const initialParams=new URLSearchParams(location.search);const pageType=document.body.dataset.tabType||initialParams.get('type')||DEFAULT_SEARCH_TYPE;const initial=initialParams.get('q')||'';const isTabPage=Boolean(document.body.dataset.tabType);if(isTabPage||initial||['web','answers','images','videos','news','local','events'].includes(pageType))runSearch(initial,Number(initialParams.get('page')||1),pageType==='info'?'web':pageType);else home();
